describe('Homepage Hero Section Responsiveness', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display hero section with large image and text on desktop', () => {
    cy.viewport('1920x1080');
    cy.get('[data-testid="hero-section"]').should('be.visible');
    cy.get('[data-testid="hero-image"]').should('have.attr', 'src');
    cy.get('[data-testid="hero-image"]').should('have.css', 'width', '100%');
    cy.get('[data-testid="hero-text"]').should('be.visible');
    cy.get('[data-testid="hero-text"]').should('contain', 'Welcome to Our Site');
    cy.get('[data-testid="hero-cta"]').should('be.visible');
    cy.get('[data-testid="hero-cta"]').should('contain', 'Get Started');
  });

  it('should display hero section with smaller image and condensed text on mobile', () => {
    cy.viewport('480x854');
    cy.get('[data-testid="hero-section"]').should('be.visible');
    cy.get('[data-testid="hero-image"]').should('have.attr', 'src');
    cy.get('[data-testid="hero-image"]').should('have.css', 'width', '100%');
    cy.get('[data-testid="hero-text"]').should('be.visible');
    cy.get('[data-testid="hero-text"]').should('contain', 'Welcome to Our Site');
    cy.get('[data-testid="hero-cta"]').should('be.visible');
    cy.get('[data-testid="hero-cta"]').should('contain', 'Get Started');
    cy.get('[data-testid="hero-cta"]').should('have.css', 'font-size', '1.2rem');
  });
});
